// Persist + Eval-extractor (n8n-workflow.md §8)
const SB=$env.SUPABASE_URL+'/rest/v1/';
const HW={ apikey:$env.SUPABASE_SERVICE_ROLE_KEY, Authorization:'Bearer '+$env.SUPABASE_SERVICE_ROLE_KEY, 'Content-Type':'application/json', Prefer:'return=representation' };
const post=(p,b)=>this.helpers.httpRequest({method:'POST',url:SB+p,headers:HW,body:b,json:true});
const patch=(p,b)=>this.helpers.httpRequest({method:'PATCH',url:SB+p,headers:{...HW},body:b,json:true});
const ctx=$('Context Loader').first().json.contextBundle;
const intent=$('Parse Router').first().json._intent;

// AI Agent output text -> parsed JSON envelope
let out={};
const raw=$json.output!==undefined?$json.output:$json.text;
try { out=typeof raw==='string'?JSON.parse(raw):raw; } catch(e){ out={ reply:String(raw||''), actions:[], eval:{} }; }
const ev=out.eval||{};
const agentName=out.agent||intent;

// which specialist handled it (from node) — map intent->agent label
const agentLabel={ book:'new_booking', reschedule:'reschedule_cancel', cancel:'reschedule_cancel', emergency:'emergency_triage', pricing:'pricing_quote', out_of_area:'out_of_area', faq:'general_faq' }[intent]||'general_faq';

// user turn
await post('messages',{ org_id:ctx.org_id, conversation_id:ctx.conversation_id, role:'user', content:ctx.message_text, question:ctx.message_text, intent, });
// assistant turn with eval fields + tool_calls (incl external_message_id)
const am=await post('messages',{ org_id:ctx.org_id, conversation_id:ctx.conversation_id, role:'assistant', content:out.reply||'', question:ev.question||ctx.message_text, response:ev.response||out.reply||'', citation:ev.citation||null, reasoning:ev.reasoning||null, intent, agent:agentLabel, tool_calls:{ actions:out.actions||[], external_message_id:ctx.message_id } });
const arow=Array.isArray(am)?am[0]:am;

// conversation status
const actions=out.actions||[];
let status='open';
if(out.handoff==='emergency'||actions.some(x=>/escalate|log_emergency/.test(x.type||''))) status='escalated';
else if(actions.some(x=>x.type==='create_appointment')) status='booked';
await patch('conversations?id=eq.'+ctx.conversation_id,{ last_intent:intent, status });

return [{ json: {
  ok:true,
  reply: out.reply||'',
  intent,
  agent: agentLabel,
  actions,
  conversation_id: ctx.conversation_id,
  message_id: arow&&arow.id,
  billed:true,
  eval: { question: ev.question||ctx.message_text, response: ev.response||out.reply||'', citation: ev.citation||'', reasoning: ev.reasoning||'' },
} }];

// Fallback Handler (n8n-workflow.md §10, eval Ha-09)
let ctx=null;
try { ctx=$('Context Loader').first().json.contextBundle; } catch(e){}
const legal=(ctx&&ctx.business&&ctx.business.legal_name)||'our team';
const text=(ctx&&ctx.message_text)||'';
const emergencyish=/gas|fire|flood|burst|no heat|carbon monoxide|smoke|sewage|leak|injur|911/i.test(text);
const reply=emergencyish
  ? "If this is an emergency, please call 911 or your gas utility now. I'm having a brief technical issue and the on-call tech is being alerted."
  : "Thanks for reaching out to "+legal+" — I'm having a brief issue on my end. The owner has been notified and will follow up shortly.";
try {
  if(ctx){
    const SB=$env.SUPABASE_URL+'/rest/v1/';
    const HW={ apikey:$env.SUPABASE_SERVICE_ROLE_KEY, Authorization:'Bearer '+$env.SUPABASE_SERVICE_ROLE_KEY, 'Content-Type':'application/json', Prefer:'return=representation' };
    const post=(p,b)=>this.helpers.httpRequest({method:'POST',url:SB+p,headers:HW,body:b,json:true});
    await post('messages',{ org_id:ctx.org_id, conversation_id:ctx.conversation_id, role:'assistant', content:reply, question:text, response:reply, intent:'fallback', agent:'fallback', tool_calls:{ external_message_id:ctx.message_id } });
    await post('notifications',{ org_id:ctx.org_id, channel:'owner', kind:'escalation', ref_id:null });
    if(emergencyish){ await post('escalations',{ org_id:ctx.org_id, conversation_id:ctx.conversation_id, end_customer_id:ctx.end_customer_id, type:'emergency', severity:'emergency', target:'owner', guidance_sent:reply }); }
    await this.helpers.httpRequest({method:'PATCH',url:SB+'conversations?id=eq.'+ctx.conversation_id,headers:HW,body:{ last_intent:'fallback' },json:true});
  }
} catch(e){}
return [{ json: { ok:true, intent:'fallback', agent:'fallback', reply, billed:false, conversation_id: ctx&&ctx.conversation_id } }];
